"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[453],{453:e=>{e.exports=JSON.parse('{"slug":"samsung-rekord-pamyat-smartfony-ceny","locale":"es","title":"Samsung gana un r\xe9cord de $80 mil millones trimestrales por la escasez de memoria y suben los tel\xe9fonos","description":"Samsung estima 107,4 billones de wones de beneficio operativo en el tercer trimestre de 2026. Por qu\xe9 la memoria para IA encarece los tel\xe9fonos en el mundo y Rusia.","blocks":[{"id":"b001","kind":"paragraph","text":"Samsung Electronics estim\xf3 el 8 de octubre de 2026 un beneficio operativo trimestral de 107,4 billones de wones, unos $80,2 mil millones. Un a\xf1o antes eran 12,2 billones: casi 9 veces m\xe1s. La facturaci\xf3n se multiplic\xf3 por m\xe1s de 2, hasta cerca de 195 billones. El r\xe9cord anterior, de 89,5 billones, era del segundo trimestre de 2026. Los analistas esperaban algo m\xe1s, unos 108 billones."},{"id":"b002","kind":"paragraph","text":"La memoria impulsa el beneficio, especialmente la de servidores de inteligencia artificial. Usa f\xe1bricas de memoria para m\xf3viles y port\xe1tiles, pero se vende mucho m\xe1s cara. Es una panader\xeda cuyo restaurante paga 3 veces m\xe1s por pasteles que la tienda por pan: los hornos son los mismos y se hornea menos pan. Una f\xe1brica nueva tarda a\xf1os. El beneficio perdido al producir memoria convencional en vez de servidores es el coste de oportunidad."},{"id":"b003","kind":"paragraph","text":"La memoria m\xf3vil multiplic\xf3 su precio por casi 3 en el segundo trimestre de 2026 frente al cuarto de 2025. Desde principios de 2026, m\xe1s del 40% de los modelos de tel\xe9fono subieron, un 15% de media. Los nuevos de 2026 cuestan un 25% m\xe1s que sus predecesores. Se fabrica y compra menos: Counterpoint revis\xf3 en junio las entregas de 2026 a una ca\xedda del 13,9%, hasta 1,08 mil millones. La divisi\xf3n Galaxy registr\xf3 su primera p\xe9rdida operativa en el segundo trimestre, de 0,7 billones de wones, por la memoria cara."},{"id":"b004","kind":"paragraph","text":"En 37 semanas de 2026 se vendieron 15,2 millones de m\xf3viles en Rusia, un 11,7% menos. El precio medio pagado creci\xf3 un 7,6%, hasta 25,8 mil rublos; depende de tarifas y de qu\xe9 elige el comprador. Los econ\xf3micos recortan memoria: el Redmi 17 de septiembre, desde 18 mil rublos, incluye 4 GB de RAM. Del 29 de septiembre al 5 de octubre, los tel\xe9fonos subieron un 1,1% y los televisores un 1%. Son importados: del 1 al 6 de octubre, el d\xf3lar oficial pas\xf3 de 83,56 a 84,93 rublos, por lo que no todo el avance viene de la memoria."},{"id":"b005","kind":"paragraph","text":"TrendForce prev\xe9 que la memoria convencional suba otro 10–15% en los contratos del cuarto trimestre de 2026 frente al tercero, y la memoria flash un 15–20%. Kim Jae-june espera escasez durante todo 2026 y gran parte de 2027, quiz\xe1 hasta 2028. Kwak Noh-jung, de SK hynix, cree que 2027 podr\xeda ser el peor a\xf1o de suministro de la historia del sector."},{"id":"b006","kind":"paragraph","text":"Un tel\xe9fono cuesta hoy m\xe1s que hace un a\xf1o. Puedes esperar, pero los propios fabricantes prev\xe9n escasez tambi\xe9n en 2027. Un rublo m\xe1s fuerte suavizar\xeda la subida y uno m\xe1s d\xe9bil la agravar\xeda."},{"id":"b007","kind":"heading","text":"\xbfPor qu\xe9 suben los tel\xe9fonos en 2026?"},{"id":"b008","kind":"paragraph","text":"Por la falta de memoria. Las f\xe1bricas priorizan la memoria cara para servidores de IA y escasea la convencional. La memoria m\xf3vil multiplic\xf3 su precio por casi 3 en el segundo trimestre de 2026 frente al cierre de 2025; los tel\xe9fonos mundiales suben un 15% medio desde enero."},{"id":"b009","kind":"heading","text":"\xbfCu\xe1nto subieron en Rusia?"},{"id":"b010","kind":"paragraph","text":"En 37 semanas de 2026, el precio medio pagado aument\xf3 un 7,6%, hasta 25,8 mil rublos, y las unidades vendidas cayeron un 11,7%. Del 29 de septiembre al 5 de octubre, el precio subi\xf3 un 1,1%."},{"id":"b011","kind":"heading","text":"\xbfCu\xe1ndo terminar\xe1 la escasez?"},{"id":"b012","kind":"paragraph","text":"No hay promesa. Samsung la prev\xe9 durante todo 2026 y gran parte de 2027, quiz\xe1 hasta 2028. SK hynix advierte de que 2027 podr\xeda ser el peor a\xf1o de suministro de la industria."}],"sources":[{"label":"Samsung estima un beneficio operativo r\xe9cord de $80 mil millones en el tercer trimestre de 2026","url":"https://sammyguru.com/samsung-estimates-record-80-billion-operating-profit-q3-2026/"},{"label":"Samsung prev\xe9 $80 mil millones trimestrales por la demanda de chips de IA","url":"https://www.cnbc.com/2026/10/08/samsung-q3-earnings.html"},{"label":"El beneficio de Samsung se multiplica por nueve hasta unos $80 mil millones","url":"https://startupfortune.com/samsungs-quarterly-profit-jumped-ninefold-to-roughly-80-billion-on-ai-chips/"},{"label":"La divisi\xf3n Galaxy registra su primera p\xe9rdida trimestral","url":"https://www.phonearena.com/news/samsung-mobile-experience-unit-first-quarterly-loss_id182207"},{"label":"Empeorar\xe1: subida mundial sin control de los tel\xe9fonos","url":"https://www.cnews.ru/news/top/2026-09-04_dalshe_budet_huzhev_mire"},{"label":"La escasez de memoria congela el mercado: entregas de 2026 caer\xedan un 13.9%","url":"https://finance.biggo.com/news/o46al54B6tLPsnrZsogu"},{"label":"La demanda de servidores de IA sostiene las subidas de memoria en 4Q26","url":"https://www.trendforce.com/presscenter/news/20260930-13258.html"},{"label":"Los rusos compran menos tel\xe9fonos","url":"https://3dnews.ru/1149266"},{"label":"Inflaci\xf3n rusa del 29 de septiembre al 5 de octubre","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"},{"label":"Samsung espera escasez de RAM durante 2027, quiz\xe1 2028","url":"https://www.pcworld.com/article/3203764/samsung-warns-the-ram-shortage-will-last-through-2027-maybe-2028.html"},{"label":"SK hynix advierte de la peor escasez hist\xf3rica en 2027","url":"https://propakistani.pk/2026/07/13/sk-hynix-warns-memory-shortage-will-be-worst-ever-in-2027/"}],"sourceBodySha256":"9109ae1c3a0a697fc17c90fd75c97bd35553c9ab1d7901b4a84036a4db6a8302"}')}}]);